import { MeshBasicNodeMaterial } from 'three/webgpu';
import { texture, uv, mul, vec2, add } from 'three/tsl';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, Mesh, PlaneGeometry, Color } = THREE;

  const root = new Group();

  if (config.position) root.position.set(...config.position);
  if (config.rotation) root.rotation.set(...config.rotation);
  if (config.scale) root.scale.set(...config.scale);

  // Atlas region (hard‑coded for this spec)
  const region = { x: 0, y: 0, width: 512, height: 320 };
  const aspect = region.width / region.height; // 1.6

  const geometry = new PlaneGeometry(aspect, 1, 1, 1);

  const material = new MeshBasicNodeMaterial();
  material.color = new Color(0xffffff);

  // UV transform for atlas region (normalized)
  const uvScale = vec2(region.width / region.width, region.height / region.height);
  const uvOffset = vec2(region.x / region.width, region.y / region.height);
  const transformedUV = add(mul(uv(), uvScale), uvOffset);

  // Placeholder texture node; will be replaced when texture loads
  let texNode = texture(null, transformedUV);
  material.mapNode = texNode;

  // Load texture
  const texturePromise = ctx.textureLoader
    .loadTexture(config.imageUrl)
    .then((tex) => {
      texNode.value = tex;
      material.needsUpdate = true;
    })
    .catch(() => {
      // keep white placeholder on failure
    });

  const mesh = new Mesh(geometry, material);
  // Simple billboard: align plane to camera each frame
  mesh.onBeforeRender = (renderer, scene, camera) => {
    mesh.quaternion.copy(camera.quaternion);
  };
  root.add(mesh);

  // ----- Text Content -----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const textObjects = [];

  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize ?? 39,
      color: item.role === 'headline' ? (config.visual?.colors?.paper ?? '#e8ecf2') : (config.visual?.colors?.ink ?? '#16161d'),
      align: 'center',
    });
    // Slightly offset forward so it renders over the plane
    txt.position.set(0, 0, 0.01);
    root.add(txt);
    textObjects.push(txt);
  }

  // Event handlers placeholder
  root.userData.handlers = {};

  // Cleanup
  root.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();

    if (texNode?.value && texNode.value.dispose) {
      texNode.value.dispose();
    }

    // Dispose any text objects if they expose dispose
    for (const txt of textObjects) {
      if (txt.parent) txt.parent.remove(txt);
      if (txt.dispose) txt.dispose();
    }

    gsap.globalTimeline.clear();
  };

  return root;
}
